function prioritizePrefetch(name) {
  if (prefetched.has(name)) return;
  prefetchQueue = prefetchQueue.filter(n => n !== name);
  prefetchQueue.unshift(name);
}
div.addEventListener('mouseenter',  () => prioritizePrefetch(name));
div.addEventListener('touchstart',  () => prioritizePrefetch(name), { passive: true });

